// Newest first, flattened to {slug, ...post}.
export function sortedPosts() {
  return Object.entries(blogPosts)
    .map(([slug, p]) => ({ slug, ...p }))
    .sort((a, b) => (String(a.date) < String(b.date) ? 1 : -1));
}
